use clap::{Command, Arg, ArgAction, value_parser, builder::PossibleValuesParser};

#[derive(Debug, Clone)]
struct Highlight(String);

fn parse_highlight(s: &str) -> Result<Highlight, String> {
    // Expected format COLOR:word1,word2,...
    let Some((color, _rest)) = s.split_once(':') else {
        return Err(format!("Expected format COLOR:word1,word2,... found `{}`", s));
    };
    let valid = ["red","green","yellow","blue","magenta","cyan"];
    if !valid.contains(&color.to_lowercase().as_str()) {
        return Err(format!("invalid variant: {}", color));
    }
    Ok(Highlight(s.to_string()))
}

fn main() {
    let cmd = Command::new("tspin")
        .version("5.6.0")
        .about("A log file highlighter")
        .arg(Arg::new("FILE").help("Filepath"))
        .arg(Arg::new("follow").short('f').long("follow").help("Follow the contents of a file").action(ArgAction::SetTrue))
        .arg(Arg::new("print").short('p').long("print").help("Print the output to stdout").action(ArgAction::SetTrue))
        .arg(Arg::new("config-path").long("config-path").value_name("CONFIG_PATH").help("Provide a custom path to a configuration file").action(ArgAction::Set))
        .arg(Arg::new("exec").short('e').long("exec").value_name("EXEC").help("Run command and view the output in a pager").action(ArgAction::Set))
        .arg(Arg::new("highlight").long("highlight").value_name("COLOR_WORD").help("Highlights in the form color:word1,word2").value_parser(value_parser!(String)).action(ArgAction::Append))
        .arg(Arg::new("enable").long("enable").value_name("ENABLED_HIGHLIGHTERS").help("Enable specific highlighters").value_parser(PossibleValuesParser::new(["numbers","urls","pointers","dates","paths","quotes","key-value-pairs","uuids","ip-addresses","processes","json"])).value_delimiter(',').action(ArgAction::Append))
        .arg(Arg::new("disable").long("disable").value_name("DISABLED_HIGHLIGHTERS").help("Disable specific highlighters").value_parser(PossibleValuesParser::new(["numbers","urls","pointers","dates","paths","quotes","key-value-pairs","uuids","ip-addresses","processes","json"])).value_delimiter(',').action(ArgAction::Append))
        .arg(Arg::new("disable-builtin-keywords").long("disable-builtin-keywords").help("Disable the highlighting of all builtin keyword groups (booleans, nulls, log severities and common REST verbs)").action(ArgAction::SetTrue))
        .arg(Arg::new("pager").long("pager").value_name("PAGER").help("Override the default pager command used by tspin. (e.g. `--pager=\"ov -f [FILE]\"`)").env("TAILSPIN_PAGER").action(ArgAction::Set));
    let m = cmd.clone().try_get_matches_from(std::env::args()).unwrap_or_else(|e| e.exit());
    println!("{:?}", m);
}
