#[derive(Debug, Clone)]
struct HighlightParser;

impl TypedValueParser for HighlightParser {
    type Value = String;
    fn parse_ref(&self, cmd: &Command, arg: Option<&Arg>, value: &std::ffi::OsStr) -> Result<Self::Value, clap::Error> {
        let s = value.to_str().unwrap_or("");
        let arg_str = arg.map(|a| a.to_string()).unwrap_or_else(|| "--highlight <COLOR_WORD>".to_owned());
        if let Some((color, _rest)) = s.split_once(':') {
            let valid = ["red","green","yellow","blue","magenta","cyan"];
            if !valid.contains(&color.to_lowercase().as_str()) {
                return Err(clap::Error::value_validation(arg_str, s.to_owned(), format!("invalid variant: {}", color).into()).with_cmd(cmd));
            }
            Ok(s.to_string())
        } else {
            return Err(clap::Error::value_validation(arg_str, s.to_owned(), format!("Expected format COLOR:word1,word2,... found `{}`", s).into()).with_cmd(cmd));
        }
    }
