        if let Some(p) = cfg.paths {
            if let Some(s) = p.segment { t.paths_segment = s; }
            if let Some(s) = p.separator { t.paths_separator = s; }
        }
        if let Some(q) = cfg.quotes {
            if let Some(s) = q.style { t.quotes_style = s; }
        }
        if let Some(kv) = cfg.key_value_pairs {
            if let Some(s) = kv.key { t.kv_key = s; }
            if let Some(s) = kv.separator { t.kv_separator = s; }
        }
        if let Some(u) = cfg.uuids {
