            if let Some(s) = u.letter { t.uuids_letter = s; }
            if let Some(s) = u.dash { t.uuids_dash = s; }
        }
        if let Some(ip) = cfg.ip_addresses {
            if let Some(s) = ip.number { t.ip_number = s; }
            if let Some(s) = ip.letter { t.ip_letter = s; }
            if let Some(s) = ip.separator { t.ip_separator = s; }
        }
        if let Some(pr) = cfg.processes {
            if let Some(s) = pr.name { t.proc_name = s; }
            if let Some(s) = pr.id { t.proc_id = s; }
            if let Some(s) = pr.bracket { t.proc_bracket = s; }
        }
        if let Some(j) = cfg.json {
            if let Some(s) = j.key { t.json_key = s; }
            if let Some(s) = j.comma { t.json_comma = s; }
            if let Some(s) = j.colon { t.json_colon = s; }
            if let Some(s) = j.curly_bracket { t.json_curly = s; }
            if let Some(s) = j.square_bracket { t.json_square = s; }
        }
        if let Some(p) = cfg.pointers {
            if let Some(s) = p.number { t.ptr_number = s; }
            if let Some(s) = p.letter { t.ptr_letter = s; }
            if let Some(s) = p.x { t.ptr_x = s; }
            if let Some(s) = p.separator { t.ptr_separator = s; }
        }
        if let Some(kws) = cfg.keywords {
            t.keywords = kws;
        }
        t
    }
