use crate::config::Theme;
use crate::style::{Style, Color};
use std::sync::OnceLock;
use regex::Regex;

// Highlight options
#[derive(Debug, Clone)]
pub struct HighlightOpts {
    pub enable: Option<Vec<String>>,
    pub disable: Vec<String>,
    pub disable_builtin: bool,
    pub custom_highlights: Vec<(Color, Vec<String>)>,
}

impl HighlightOpts {
    pub fn is_enabled(&self, name: &str) -> bool {
        if let Some(en) = &self.enable {
            en.contains(&name.to_string())
        } else {
            !self.disable.contains(&name.to_string())
        }
    }
}

fn style_trace() -> Style { Style { faint: true, ..Default::default() } }
fn style_debug() -> Style { Style { fg: Some(Color::Green), ..Default::default() } }
fn style_info() -> Style { Style { fg: Some(Color::White), ..Default::default() } }
fn style_warn() -> Style { Style { fg: Some(Color::Yellow), ..Default::default() } }
fn style_error() -> Style { Style { fg: Some(Color::Red), ..Default::default() } }
fn style_success() -> Style { Style { fg: Some(Color::Green), ..Default::default() } }
fn style_bool() -> Style { Style { fg: Some(Color::Red), italic: true, ..Default::default() } }
fn style_get() -> Style { Style { fg: Some(Color::Black), bg: Some(Color::Green), ..Default::default() } }
fn style_post() -> Style { Style { fg: Some(Color::Black), bg: Some(Color::Yellow), ..Default::default() } }
fn style_put() -> Style { Style { fg: Some(Color::Black), bg: Some(Color::Magenta), ..Default::default() } }
fn style_delete() -> Style { Style { fg: Some(Color::Black), bg: Some(Color::Red), ..Default::default() } }
fn style_patch() -> Style { Style { fg: Some(Color::Black), bg: Some(Color::Magenta), ..Default::default() } }
fn style_red() -> Style { Style { fg: Some(Color::Red), ..Default::default() } }
fn style_magenta() -> Style { Style { fg: Some(Color::Magenta), ..Default::default() } }
fn style_cyan() -> Style { Style { fg: Some(Color::Cyan), ..Default::default() } }

fn word_boundary(s: &str, start: usize, end: usize) -> bool {
    let bytes = s.as_bytes();
    let is_word = |c: u8| c.is_ascii_alphanumeric() || c == b'_';
    if start > 0 {
        if is_word(bytes[start-1]) {
            return false;
        }
    }
    if end < bytes.len() {
        if is_word(bytes[end]) {
            return false;
        }
    }
    true
}

#[derive(Debug, Clone)]
struct HRange {
    start: usize,
    end: usize,
    styled: String,
}

fn overlaps(ranges: &[HRange], s: usize, e: usize) -> bool {
    for r in ranges {
        if s < r.end && e > r.start {
            return true;
        }
    }
    false
}

pub fn highlight_line(line: &str, theme: &Theme, opts: &HighlightOpts) -> String {
    if opts.is_enabled("json") {
        let trimmed = line.trim();
        if !trimmed.is_empty() {
            if let Ok(val) = serde_json::from_str::<serde_json::Value>(trimmed) {
                return format_json(&val, theme, opts);
            }
        }
    }
    let mut ranges: Vec<HRange> = Vec::new();
    if opts.is_enabled("key-value-pairs") {
        highlight_kv(line, &mut ranges, theme);
    }
    if opts.is_enabled("dates") {
        highlight_dates(line, &mut ranges, theme);
    }
    if opts.is_enabled("ip-addresses") {
        highlight_ips(line, &mut ranges, theme);
    }
    if opts.is_enabled("urls") {
        highlight_urls(line, &mut ranges, theme);
    }
    if opts.is_enabled("paths") {
        highlight_paths(line, &mut ranges, theme);
    }
    if opts.is_enabled("uuids") {
        highlight_uuids(line, &mut ranges, theme);
    }
    if opts.is_enabled("pointers") {
        highlight_pointers(line, &mut ranges, theme);
    }
    if opts.is_enabled("processes") {
        highlight_processes(line, &mut ranges, theme);
    }
    if opts.is_enabled("numbers") {
        highlight_numbers(line, &mut ranges, theme);
    }
    if !opts.disable_builtin {
        highlight_builtin(line, &mut ranges);
    }
    highlight_custom_cli(line, &mut ranges, opts);
    highlight_config_keywords(line, &mut ranges, theme);
    if opts.is_enabled("quotes") {
        highlight_quotes(line, &mut ranges, theme);
    }
    reconstruct(line, &ranges)
}

fn reconstruct(line: &str, ranges: &[HRange]) -> String {
    let mut sorted: Vec<&HRange> = ranges.iter().collect();
    sorted.sort_by_key(|r| r.start);
    let mut out = String::new();
    let mut pos = 0;
    for r in sorted {
        if r.start < pos {
            continue;
        }
        if r.start > pos {
            out.push_str(&line[pos..r.start]);
        }
        out.push_str(&r.styled);
        pos = r.end;
    }
    if pos < line.len() {
        out.push_str(&line[pos..]);
    }
    out
}

fn highlight_numbers(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = numbers_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) {
            continue;
        }
        let text = &line[s..e];
        let styled = theme.numbers_number.apply(text);
        ranges.push(HRange { start: s, end: e, styled });
    }
}

fn numbers_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"\b\d+(?:\.\d+)?\b").unwrap())
}

fn highlight_builtin(line: &str, ranges: &mut Vec<HRange>) {
    let re = builtin_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) {
            continue;
        }
        let text = &line[s..e];
        let style = match text {
            "TRACE" => style_trace(),
            "DEBUG" => style_debug(),
            "INFO" => style_info(),
            "WARN" => style_warn(),
            "ERROR" => style_error(),
            "SUCCESS" => style_success(),
            "true" | "false" | "null" => style_bool(),
            "GET" => style_get(),
            "POST" => style_post(),
            "PUT" => style_put(),
            "DELETE" => style_delete(),
            "PATCH" => style_patch(),
            _ => continue,
        };
        let styled = style.apply(text);
        ranges.push(HRange { start: s, end: e, styled });
    }
}

fn builtin_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"\b(?:TRACE|DEBUG|INFO|WARN|ERROR|SUCCESS|true|false|null|GET|POST|PUT|DELETE|PATCH)\b").unwrap())
}

fn highlight_custom_cli(line: &str, ranges: &mut Vec<HRange>, opts: &HighlightOpts) {
    if opts.custom_highlights.is_empty() {
        return;
    }
    let mut all: Vec<(usize, Style, String)> = Vec::new();
    for (color, words) in &opts.custom_highlights {
        let prio = match color {
            Color::Red => 0,
            Color::Green => 1,
            Color::Yellow => 2,
            Color::Blue => 3,
            Color::Magenta => 4,
            Color::Cyan => 5,
            _ => 6,
        };
        let style = Style { fg: Some(*color), ..Default::default() };
        for w in words {
            if w.is_empty() { continue; }
            all.push((prio, style.clone(), w.clone()));
        }
    }
    struct Match { prio: usize, start: usize, end: usize, styled: String }
    let mut matches: Vec<Match> = Vec::new();
    for (prio, style, word) in all {
        let mut pos = 0;
        while pos <= line.len() {
            if let Some(idx) = line[pos..].find(&word) {
                let s = pos + idx;
                let e = s + word.len();
                if word_boundary(line, s, e) && !overlaps(ranges, s, e) {
                    let styled = style.apply(&word);
                    matches.push(Match { prio, start: s, end: e, styled });
                }
                pos = s + 1;
                if pos >= line.len() { break; }
            } else {
                break;
            }
        }
    }
    matches.sort_by(|a, b| a.prio.cmp(&b.prio).then(a.start.cmp(&b.start)));
    let mut added: Vec<HRange> = Vec::new();
    for m in matches {
        if overlaps(ranges, m.start, m.end) { continue; }
        let mut ov = false;
        for a in &added {
            if m.start < a.end && m.end > a.start { ov = true; break; }
        }
        if ov { continue; }
        let hr = HRange { start: m.start, end: m.end, styled: m.styled };
        added.push(hr.clone());
        ranges.push(hr);
    }
}

fn highlight_config_keywords(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
