fn highlight_kv(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let bytes = line.as_bytes();
    let mut i = 0;
    while i < line.len() {
        if i > 0 && !(bytes[i-1] == b' ' || bytes[i-1] == b'\t') {
            i += 1;
            continue;
        }
        let mut j = i;
        while j < line.len() && (bytes[j].is_ascii_alphanumeric() || bytes[j] == b'_') {
            j += 1;
        }
        if j == i {
            i += 1;
            continue;
        }
        if j >= line.len() || bytes[j] != b'=' {
            i = j;
            if i == 0 { i = 1; }
            if i <= j && j == i { i += 1; }
            // avoid infinite: ensure progress
            if i == j && j == i {
                i += 1;
            } else if i == 0 {
                i = 1;
            }
            // Actually j > i (since key non-empty), so i=j advances. Good.
            // But need to handle case where j==i (no key) already handled above with i+=1. Good.
            // For this branch (key found but no "="), i=j advances (since j>i). Good.
            continue;
        }
        let key_s = i;
        let key_e = j;
        let eq_s = j;
        let eq_e = j + 1;
        if overlaps(ranges, key_s, eq_e) {
            i = j + 1;
            continue;
        }
        let key_text = &line[key_s..key_e];
        let key_styled = theme.kv_key.apply(key_text);
        ranges.push(HRange { start: key_s, end: key_e, styled: key_styled });
        let eq_styled = theme.kv_separator.apply("=");
        ranges.push(HRange { start: eq_s, end: eq_e, styled: eq_styled });
        let val_start = eq_e;
        let mut val_end = val_start;
        if val_start < line.len() && bytes[val_start] == b'"' {
            if let Some(closing) = line[val_start+1..].find('"') {
                val_end = val_start + 1 + closing + 1;
            } else {
                let mut k = val_start;
                while k < line.len() && bytes[k] != b' ' && bytes[k] != b'\t' {
                    k += 1;
                }
                val_end = k;
            }
        } else {
            let mut k = val_start;
            while k < line.len() && bytes[k] != b' ' && bytes[k] != b'\t' {
                k += 1;
            }
            val_end = k;
        }
        i = val_end;
        if i <= key_s {
            i = key_s + 1;
        }
    }
}

fn highlight_uuids(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = uuid_regex();
    for m in re.find_iter(line) {
