fn highlight_ipv4(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = ipv4_candidate_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) { continue; }
        let text = &line[s..e];
        // Validate each octet 0-255, and word boundaries? Regex already has \b, good.
        let parts: Vec<&str> = text.split('.').collect();
        if parts.len() != 4 { continue; }
        let mut valid = true;
        for p in &parts {
            if p.is_empty() || p.len() > 3 { valid = false; break; }
            if !p.chars().all(|c| c.is_ascii_digit()) { valid = false; break; }
            if let Ok(n) = p.parse::<u32>() {
                if n > 255 { valid = false; break; }
            } else { valid = false; break; }
        }
        if !valid { continue; }
        // Highlight: each octet with ip_number (as whole, not per digit? For IPv4, octets are digits only, highlight whole octet as one chunk with ip_number style? Earlier 192 -> single chunk \x1b[3;34m192, not per digit. Good. For IPv4, no letters, so whole octet.
        let mut styled = String::new();
        for (i, part) in parts.iter().enumerate() {
            if i > 0 {
                styled.push_str(&theme.ip_separator.apply("."));
            }
            styled.push_str(&theme.ip_number.apply(part));
        }
        ranges.push(HRange { start: s, end: e, styled });
    }
}
fn ipv4_candidate_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"\b\d{1,3}(?:\.\d{1,3}){3}\b").unwrap())
}

fn highlight_ipv6(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = ipv6_candidate_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) { continue; }
        let text = &line[s..e];
        // Must contain at least one hex digit (to exclude "::" alone, ":" alone)
        if !text.chars().any(|c| c.is_ascii_hexdigit()) { continue; }
        // Must contain at least one ':' (candidate regex ensures? Actually [0-9a-fA-F:]+ could be just digits without colon, like "123"? But our candidate regex requires colon? Let's ensure candidate contains ':'. If not, skip (it's just numbers, not IPv6).
        if !text.contains(':') { continue; }
        // Validate with std::net::Ipv6Addr
        if text.parse::<std::net::Ipv6Addr>().is_err() { continue; }
        // Highlight per char: digits blue italic, letters magenta italic, ':' red
        let mut styled = String::new();
        for ch in text.chars() {
            if ch == ':' {
                styled.push_str(&theme.ip_separator.apply(":"));
            } else if ch.is_ascii_digit() {
                styled.push_str(&theme.ip_number.apply(&ch.to_string()));
            } else {
                styled.push_str(&theme.ip_letter.apply(&ch.to_string()));
            }
        }
        ranges.push(HRange { start: s, end: e, styled });
    }
}
fn ipv6_candidate_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    // Match maximal [0-9a-fA-F:]+ substrings (will be validated after)
    RE.get_or_init(|| Regex::new(r"[0-9a-fA-F:]+").unwrap())
}

