fn quotes_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r#""[^"]*""#).unwrap())
}

fn highlight_kv(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let bytes = line.as_bytes();
    let mut i = 0;
    while i < line.len() {
        if i > 0 && !(bytes[i-1] == b' ' || bytes[i-1] == b'\t') {
            i += 1;
            continue;
        }
        let mut j = i;
        while j < line.len() && (bytes[j].is_ascii_alphanumeric() || bytes[j] == b'_') {
            j += 1;
        }
        if j == i {
            i += 1;
            continue;
        }
        if j >= line.len() || bytes[j] != b'=' {
            i = j;
            if i == 0 { i = 1; }
            if i <= j && j == i { i += 1; }
            // avoid infinite: ensure progress
            if i == j && j == i {
                i += 1;
            } else if i == 0 {
                i = 1;
            }
            // Actually j > i (since key non-empty), so i=j advances. Good.
            // But need to handle case where j==i (no key) already handled above with i+=1. Good.
            // For this branch (key found but no "="), i=j advances (since j>i). Good.
            continue;
        }
        let key_s = i;
        let key_e = j;
        let eq_s = j;
        let eq_e = j + 1;
        if overlaps(ranges, key_s, eq_e) {
            i = j + 1;
            continue;
        }
        let key_text = &line[key_s..key_e];
        let key_styled = theme.kv_key.apply(key_text);
        ranges.push(HRange { start: key_s, end: key_e, styled: key_styled });
        let eq_styled = theme.kv_separator.apply("=");
        ranges.push(HRange { start: eq_s, end: eq_e, styled: eq_styled });
        let val_start = eq_e;
        let mut val_end = val_start;
        if val_start < line.len() && bytes[val_start] == b'"' {
            if let Some(closing) = line[val_start+1..].find('"') {
                val_end = val_start + 1 + closing + 1;
            } else {
                let mut k = val_start;
                while k < line.len() && bytes[k] != b' ' && bytes[k] != b'\t' {
                    k += 1;
                }
                val_end = k;
            }
        } else {
            let mut k = val_start;
            while k < line.len() && bytes[k] != b' ' && bytes[k] != b'\t' {
                k += 1;
            }
            val_end = k;
        }
        i = val_end;
        if i <= key_s {
            i = key_s + 1;
        }
    }
}

fn highlight_uuids(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = uuid_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) { continue; }
        let text = &line[s..e];
        let mut styled = String::new();
        for ch in text.chars() {
            if ch == '-' {
                styled.push_str(&theme.uuids_dash.apply("-"));
            } else if ch.is_ascii_digit() {
                styled.push_str(&theme.uuids_number.apply(&ch.to_string()));
            } else {
                styled.push_str(&theme.uuids_letter.apply(&ch.to_string()));
            }
        }
        ranges.push(HRange { start: s, end: e, styled });
    }
}
fn uuid_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"\b[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}\b").unwrap())
}

fn highlight_pointers(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = pointer_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) { continue; }
        let text = &line[s..e];
        let chars: Vec<char> = text.chars().collect();
        if chars.len() != 10 { continue; }
        let mut styled = String::new();
        styled.push_str(&theme.ptr_number.apply(&chars[0].to_string()));
        styled.push_str(&theme.ptr_x.apply(&chars[1].to_string()));
        for &ch in &chars[2..] {
            if ch.is_ascii_digit() {
                styled.push_str(&theme.ptr_number.apply(&ch.to_string()));
            } else {
                styled.push_str(&theme.ptr_letter.apply(&ch.to_string()));
            }
        }
        ranges.push(HRange { start: s, end: e, styled });
    }
}
fn pointer_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"\b0[xX][0-9a-fA-F]{8}\b").unwrap())
}

fn highlight_processes(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = process_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) { continue; }
        let text = &line[s..e];
        if let Some(bracket_start) = text.find('[') {
            let name = &text[..bracket_start];
            if name.is_empty() { continue; }
            let id = &text[bracket_start+1 .. text.len()-1];
            let mut styled = String::new();
            styled.push_str(&theme.proc_name.apply(name));
            styled.push_str(&theme.proc_bracket.apply("["));
            styled.push_str(&theme.proc_id.apply(id));
            styled.push_str(&theme.proc_bracket.apply("]"));
            ranges.push(HRange { start: s, end: e, styled });
        }
    }
}
fn process_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"[A-Za-z0-9_\-/]+\[[0-9]+\]").unwrap())
}

fn highlight_paths(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = path_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) { continue; }
        let text = &line[s..e];
        // Split into separators "/" and segments
        let mut styled = String::new();
        let mut idx = 0;
        let bytes = text.as_bytes();
        // Handle leading "/"?
        let mut pos = 0;
        while pos < text.len() {
            if bytes[pos] == b'/' {
                styled.push_str(&theme.paths_separator.apply("/"));
                pos += 1;
            } else {
                // segment until next "/"
                let start = pos;
                while pos < text.len() && bytes[pos] != b'/' {
                    pos += 1;
                }
                let seg = &text[start..pos];
                styled.push_str(&theme.paths_segment.apply(seg));
            }
        }
        let _ = idx;
        ranges.push(HRange { start: s, end: e, styled });
    }
}
fn path_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"(?:/[A-Za-z0-9._-]+(?:/[A-Za-z0-9._-]+)+|[A-Za-z0-9._-]+(?:/[A-Za-z0-9._-]+){2,})").unwrap())
}

fn highlight_ips(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    highlight_ipv4(line, ranges, theme);
    highlight_ipv6(line, ranges, theme);
}

fn highlight_ipv4(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = ipv4_candidate_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) { continue; }
        let text = &line[s..e];
        // Validate each octet 0-255, and word boundaries? Regex already has \b, good.
        let parts: Vec<&str> = text.split('.').collect();
        if parts.len() != 4 { continue; }
        let mut valid = true;
        for p in &parts {
            if p.is_empty() || p.len() > 3 { valid = false; break; }
            if !p.chars().all(|c| c.is_ascii_digit()) { valid = false; break; }
            if let Ok(n) = p.parse::<u32>() {
                if n > 255 { valid = false; break; }
            } else { valid = false; break; }
        }
        if !valid { continue; }
        // Highlight: each octet with ip_number (as whole, not per digit? For IPv4, octets are digits only, highlight whole octet as one chunk with ip_number style? Earlier 192 -> single chunk \x1b[3;34m192, not per digit. Good. For IPv4, no letters, so whole octet.
        let mut styled = String::new();
        for (i, part) in parts.iter().enumerate() {
            if i > 0 {
                styled.push_str(&theme.ip_separator.apply("."));
            }
            styled.push_str(&theme.ip_number.apply(part));
        }
        ranges.push(HRange { start: s, end: e, styled });
    }
}
fn ipv4_candidate_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"\b\d{1,3}(?:\.\d{1,3}){3}\b").unwrap())
}

fn highlight_ipv6(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    let re = ipv6_candidate_regex();
    for m in re.find_iter(line) {
        let s = m.start();
        let e = m.end();
        if overlaps(ranges, s, e) { continue; }
        let text = &line[s..e];
        // Must contain at least one hex digit (to exclude "::" alone, ":" alone)
        if !text.chars().any(|c| c.is_ascii_hexdigit()) { continue; }
        // Must contain at least one ':' (candidate regex ensures? Actually [0-9a-fA-F:]+ could be just digits without colon, like "123"? But our candidate regex requires colon? Let's ensure candidate contains ':'. If not, skip (it's just numbers, not IPv6).
        if !text.contains(':') { continue; }
        // Validate with std::net::Ipv6Addr
        if text.parse::<std::net::Ipv6Addr>().is_err() { continue; }
        // Highlight per char: digits blue italic, letters magenta italic, ':' red
        let mut styled = String::new();
        for ch in text.chars() {
            if ch == ':' {
                styled.push_str(&theme.ip_separator.apply(":"));
            } else if ch.is_ascii_digit() {
                styled.push_str(&theme.ip_number.apply(&ch.to_string()));
            } else {
                styled.push_str(&theme.ip_letter.apply(&ch.to_string()));
            }
        }
        ranges.push(HRange { start: s, end: e, styled });
    }
}
fn ipv6_candidate_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    // Match maximal [0-9a-fA-F:]+ substrings (will be validated after)
    RE.get_or_init(|| Regex::new(r"[0-9a-fA-F:]+").unwrap())
}

