    // Operate on plain segments (to allow prefix highlighting when suffix is already highlighted as IP/date)
    let plain_segs = {
        let mut sorted: Vec<&HRange> = ranges.iter().collect();
        sorted.sort_by_key(|r| r.start);
        let mut segs = Vec::new();
        let mut p = 0;
        for r in sorted {
            if r.start > p {
                segs.push((p, r.start));
            }
            p = p.max(r.end);
        }
        if p < line.len() {
            segs.push((p, line.len()));
        }
        segs
    };
    for (seg_s, seg_e) in plain_segs {
        let seg = &line[seg_s..seg_e];
        let mut sp = 0;
        while sp < seg.len() {
