fn highlight_dates(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    highlight_date_ymd(line, ranges, theme);
    highlight_date_mdy(line, ranges, theme);
    highlight_time(line, ranges, theme);
    highlight_datetime_sep_and_z(line, ranges);
}

fn highlight_date_ymd(line: &str, ranges: &mut Vec<HRange>, theme: &Theme) {
    // YYYY-MM-DD or YYYY/MM/DD or mixed: \d{4}[-/]\d{2}[-/]\d{2} with validation
    let bytes = line.as_bytes();
    let mut i = 0;
    while i + 10 <= line.len() {
        // Check pattern at i: 4 digits, sep1 (- or /), 2 digits, sep2 (- or /), 2 digits
        let mut ok = true;
        for k in 0..4 {
            if !bytes[i+k].is_ascii_digit() { ok = false; break; }
        }
        if !ok { i += 1; continue; }
        if bytes[i+4] != b'-' && bytes[i+4] != b'/' { i += 1; continue; }
        if !bytes[i+5].is_ascii_digit() || !bytes[i+6].is_ascii_digit() { i += 1; continue; }
        if bytes[i+7] != b'-' && bytes[i+7] != b'/' { i += 1; continue; }
        if !bytes[i+8].is_ascii_digit() || !bytes[i+9].is_ascii_digit() { i += 1; continue; }
        let y = &line[i..i+4];
        let m = &line[i+5..i+7];
        let d = &line[i+8..i+10];
        if !is_valid_year(y) || !is_valid_md(m) || !is_valid_md(d) {
            i += 1;
            continue;
        }
        let s = i;
        let e = i + 10;
        if overlaps(ranges, s, e) { i += 1; continue; }
        // Highlight: year magenta, sep1 dim, month magenta, sep2 dim, day magenta
        // Note: no reordering for YMD (stays as is)
        ranges.push(HRange { start: s, end: s+4, styled: theme.dates_date.apply(y) });
        let sep1 = &line[s+4..s+5];
        ranges.push(HRange { start: s+4, end: s+5, styled: theme.dates_separator.apply(sep1) });
        ranges.push(HRange { start: s+5, end: s+7, styled: theme.dates_date.apply(m) });
        let sep2 = &line[s+7..s+8];
        ranges.push(HRange { start: s+7, end: s+8, styled: theme.dates_separator.apply(sep2) });
        ranges.push(HRange { start: s+8, end: s+10, styled: theme.dates_date.apply(d) });
        i = e;
    }
}

