fn get_default_config_path() -> Option<String> {
    if let Ok(xdg) = std::env::var("XDG_CONFIG_HOME") {
        if !xdg.is_empty() {
            return Some(format!("{}/tailspin/theme.toml", xdg.trim_end_matches('/')));
        }
    }
    if let Ok(home) = std::env::var("HOME") {
        if !home.is_empty() {
            return Some(format!("{}/.config/tailspin/theme.toml", home.trim_end_matches('/')));
        }
    }
    // Fallback: try expanduser via dirs? Or use /home/agent? Actually HOME should always be set. If not set, return None (no config).
    None
}

fn format_toml_error(e: &toml::de::Error) -> String {
    // Format toml error with miette-style gutters and wrapping to match original.
    // Get plain error string via e.to_string() (multi-line, no gutters, no wrapping for long messages? Actually long messages single line, need wrapping).
    let plain = e.to_string();
    let lines: Vec<&str> = plain.lines().collect();
    if lines.is_empty() {
        return format!("Error:   \u{00d7} {}\n\n", plain);
    }
    let header = lines[0]; // "TOML parse error at line X, column Y"
    let mut out = format!("Error:   \u{00d7} {}\n", header);
    // Remaining lines: snippet (up to 3 lines: "  |", "N | ...", "  | ...") + message (1+ lines? Actually message could be single long line for unknown variant, which needs wrapping).
    // For simplicity, treat all remaining lines as: first 3 are snippet (if they look like snippet?), rest are message to be wrapped?
    // Actually plain format is always: header, "  |", "N | ...", "  | ...", message (single line, possibly very long for unknown variant). For some errors, message could be multi-line? Unlikely (all messages single line). Good.
    // So lines[1..4] are snippet (3 lines), lines[4..] are message (1 line, possibly long).
    // Prefix snippet lines with "  │ " (gutter + space + original line).
    // For message lines, wrap at content width 76 (total 80 including gutter "  │ " (4 chars)) with word boundaries, each wrapped line prefixed with "  │ ".
    // Plus final "  │ \n\n" (gutter + space + newline + newline).
    if lines.len() >= 2 {
        // Snippet lines: lines[1..4] if len>=4? Actually for some errors, snippet could be different? Let's just treat lines[1..lines.len()-1] as snippet? No, last line is message, rest after header up to last are snippet. For "invalid toml [[[", lines are: [header, "  |", "1 | ...", "  | ...", "key with..."] (5 lines: header + 3 snippet + 1 message). Good. For unknown variant, lines are: [header, "  |", "3 | ...", "  | ...", "unknown variant ... (very long single line)"] (5 lines). Good. So snippet is lines[1..len-1], message is lines[len-1] (last line, single long or short).
        // But what about errors with multi-line messages? Unlikely. Assume last line is message.
        let snippet_end = lines.len() - 1;
        for i in 1..snippet_end {
            out.push_str(&format!("  \u{2502} {}\n", lines[i]));
        }
        let msg = lines[lines.len()-1];
        // Wrap msg at 76 content width (80 total - 4 gutter) with word boundaries.
        let wrapped = wrap_text(msg, 76);
        for wl in wrapped {
            out.push_str(&format!("  \u{2502} {}\n", wl));
        }
    }
    out.push_str("  \u{2502} \n\n");
    out
}

fn wrap_text(s: &str, width: usize) -> Vec<String> {
    // Simple word wrap at width, breaking on spaces, preserving words (no hyphenation).
    // If single word longer than width, break arbitrarily? For our messages, words are short (like "`bright_magenta`,", "`invalidcolor`,", etc.), all under width, so no need for arbitrary break. Good.
    // Implement greedy: accumulate words until adding next word would exceed width, then break.
    let mut lines = Vec::new();
    let mut cur = String::new();
    for word in s.split(' ') {
        if cur.is_empty() {
            cur.push_str(word);
        } else {
            // Check if cur + ' ' + word exceeds width (display width? Use char count? Since all ascii (backticks, letters, commas), char count == display width. Good. For unicode? Messages are ascii only. Good.)
            if cur.len() + 1 + word.len() > width {
                lines.push(cur);
                cur = word.to_string();
            } else {
                cur.push(' ');
                cur.push_str(word);
            }
        }
    }
    if !cur.is_empty() {
        lines.push(cur);
    }
    if lines.is_empty() {
        lines.push(String::new());
    }
    lines
}

fn handle_stdin(theme: &config::Theme, opts: &highlight::HighlightOpts) {
    // Read stdin fully as bytes, validate UTF-8
    let mut buf = Vec::new();
    if std::io::stdin().read_to_end(&mut buf).is_err() {
        // Read error? Unlikely. Treat as empty?
        return;
    }
    let content = match String::from_utf8(buf) {
        Ok(s) => s,
        Err(_) => {
            eprint!("Error:   \u{00d7} stream did not contain valid UTF-8\n\n");
            std::process::exit(1);
        }
    };
    // Split on '\n', handle trailing newline, preserve '\r' (no stripping)
    // If content empty (""): output "" (empty, no newline). Good.
    if content.is_empty() {
        return;
    }
    let ends_with_nl = content.ends_with('\n');
    let mut parts: Vec<&str> = content.split('\n').collect();
    if ends_with_nl {
        // Last element is "" due to trailing '\n', drop it
        parts.pop();
    }
    // For each part (line without '\n', preserving '\r' and other chars), highlight and output with '\n'
    let stdout = std::io::stdout();
    let mut out = stdout.lock();
    for line in parts {
        let highlighted = highlight::highlight_line(line, theme, opts);
        let _ = writeln!(out, "{}", highlighted);
    }
}

