fn file_content_to_pager_lines(content: &str, theme: &config::Theme, opts: &highlight::HighlightOpts) -> Vec<String> {
    // Pager-like logic for file content (used for initial follow output and pager temp file):
    // - If empty (""): output [""] (single empty line -> "\n")
    // - Else if no '\n' (single line, no newline, non-empty): output ["", highlighted_content]?? Actually pager for "hi" gives "\nhi\n" (leading newline + content + newline). That's 2 lines: "" (empty) + "hi" (content)? With each output via writeln (adding '\n'), ["", "hi"] would give "\n" + "hi\n" = "\nhi\n". Good. So return ["", highlighted("hi")]? But first "" is empty (no highlight, just ""), second is highlighted content. Good.
    // - Else (contains '\n'): split on '\n', if ends with '\n', drop trailing empty, output each (stripped of trailing '\r' if present? For lines followed by '\n', strip. For last line when no trailing '\n' (multi-line, no trailing), last line is partial without '\n', DON'T strip trailing '\r'? Actually last partial without '\n' should preserve trailing '\r' (as observed for "hi\r" single-line-no-newline preserves '\r', but that's single-line case, not multi-line. For multi-line-no-trailing with last line ending with '\r' (e.g., "a\nb\r" with last "b\r" no '\n'), preserve '\r'? Likely. Good. So for last line when no trailing '\n', DON'T strip.
    if content.is_empty() {
        return vec![String::new()];
    }
    if !content.contains('\n') {
        // Single line, no newline, non-empty
        // Don't strip trailing '\r' (preserve)? For "hi\r" (with '\r'), preserve. Good. So no stripping.
        let hl = highlight::highlight_line(content, theme, opts);
        return vec![String::new(), hl];
    }
    // Contains '\n'
    let ends_with_nl = content.ends_with('\n');
    let mut parts: Vec<&str> = content.split('\n').collect();
    if ends_with_nl {
        parts.pop(); // trailing empty
        let mut out = Vec::new();
        for line in parts {
            let mut l = line;
            if l.ends_with('\r') {
                l = &l[..l.len()-1];
            }
            out.push(highlight::highlight_line(l, theme, opts));
        }
        out
    } else {
        // No trailing, multi-line, preserve last (don't strip its trailing '\r'? Actually last partial without '\n', preserve '\r'. Good. For others (followed by '\n'), strip.
        let mut out = Vec::new();
        for (idx, line) in parts.iter().enumerate() {
            let is_last = idx == parts.len() - 1;
            let mut l = *line;
            if !is_last && l.ends_with('\r') {
                l = &l[..l.len()-1];
            }
            // For last, don't strip (preserve '\r')
            out.push(highlight::highlight_line(l, theme, opts));
        }
        out
    }
}

