fn generate_uuid_like() -> String {
    // Generate random 8-4-4-4-12 hex using /dev/urandom or time+pid? Use std::collections::hash_map::RandomState? Simpler: read 16 random bytes from /dev/urandom (or fallback to time).
    let mut bytes = [0u8; 16];
    if let Ok(mut f) = File::open("/dev/urandom") {
        use std::io::Read;
        let _ = f.read_exact(&mut bytes);
    } else {
        // Fallback: use time + pid
        let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_nanos()).unwrap_or(0);
        let pid = std::process::id() as u128;
        let mut x = now ^ ((pid as u128) << 64);
        for i in 0..16 {
            bytes[i] = (x & 0xff) as u8;
            x >>= 8;
            if x == 0 {
                x = now.wrapping_add(i as u128);
            }
        }
    }
    // Format as 8-4-4-4-12 hex (lowercase)
    format!("{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        bytes[0], bytes[1], bytes[2], bytes[3],
        bytes[4], bytes[5],
        bytes[6], bytes[7],
        bytes[8], bytes[9],
        bytes[10], bytes[11], bytes[12], bytes[13], bytes[14], bytes[15])
}

