            let http_pos = rem.find("http://");
            let https_pos = rem.find("https://");
            let (is_https, rel) = match (http_pos, https_pos) {
                (Some(h), Some(s)) => if s < h { (true, s) } else { (false, h) },
                (Some(h), None) => (false, h),
                (None, Some(s)) => (true, s),
                (None, None) => break,
            };
            let abs_rel = sp + rel;
            if let Some((url_len, host_range, path_range, query_range)) = parse_url_in_plain(&seg[abs_rel..]) {
                let url_start = seg_s + abs_rel;
                let url_end = seg_s + abs_rel + url_len;
                if overlaps(ranges, url_start, url_end) {
                    sp = abs_rel + 1;
                    continue;
                }
                let scheme_len = if is_https { 5 } else { 4 };
                let scheme_s = url_start;
                let scheme_e = scheme_s + scheme_len;
                let scheme_text = &line[scheme_s..scheme_e];
                let scheme_style = if is_https { &theme.urls_https } else { &theme.urls_http };
                ranges.push(HRange { start: scheme_s, end: scheme_e, styled: scheme_style.apply(scheme_text) });
                if let Some((hs, he)) = host_range {
                    let hs_abs = seg_s + abs_rel + hs;
                    let he_abs = seg_s + abs_rel + he;
                    let host_text = &line[hs_abs..he_abs];
                    ranges.push(HRange { start: hs_abs, end: he_abs, styled: theme.urls_host.apply(host_text) });
